&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;Lead AI-enabled operations &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;programmes&lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt; end to &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;end:&lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt; from diagnostics, baselines and business cases, &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;through process and operating model redesign, to implementation, adoption and value &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;realisation&lt;/span&gt;​&lt;/li&gt;
&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;Shape AI and operational transformation strategies and roadmaps tailored to each client’s needs, &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;working closely with COOs, CFOs, technology leaders and other senior stakeholders&lt;/span&gt;​&lt;/li&gt;
&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;Oversee systems integrators, technology vendors and internal delivery teams, making sure solutions &lt;/span&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;meet business needs and are delivered to scope and quality&lt;/span&gt;​&lt;/li&gt;
&lt;li data-charcodes=&quot;8226&quot; data-font=&quot;Arial,Sans-Serif&quot; data-buautonum=&quot;8&quot; data-margin=&quot;270&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-usefontface=&quot;false&quot; data-contrast=&quot;none&quot;&gt;Lead multi-disciplinary teams, bringing together expertise from across Baringa&lt;/span&gt;​&lt;/li&gt;
